      "id": 2,
      "claim": "George Washington's actual birthday is February 22.",
      "evidence": "Biographical data list Washington's birth date as 1732‑02‑22.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "The federal holiday called \"Washington's Birthday\" (commonly known as Presidents' Day) is observed on the third Monday of February, not on February 22.",
      "evidence": "U.S. Code (5 U.S.C. § 6103) designates the holiday on the third Monday of February; the holiday name is \"Washington's Birthday\" but the date differs from his actual birthday.",
      "weight": 0.25,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "The United States Postal Service does not deliver regular mail on federal holidays, including the holiday observed on the third Monday of February.",
      "evidence": "USPS operational schedule lists no regular mail delivery on all federal holidays, such as Washington's Birthday/Presidents' Day.",
      "weight": 0.15,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "Therefore, mail carriers have a day off on the third Monday of February, but not on February 22, Washington's actual birthday.",
      "evidence": "Combining steps 3 and 4 shows the break aligns with the holiday date, not the calendar birthday.",
      "weight": 0.10,
      "depends_on": [2, 3, 4]
    }
  ],
